const $=s=>document.querySelector(s),money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles={painel:'Início',pedidos:'Pedidos',cardapio:'Cardápio',alunos:'Alunos e responsáveis',extratos:'Histórico',relatorios:'Relatórios'};
const today=()=>new Date().toLocaleDateString('en-CA');
let db={products:[],students:[],orders:[]},token='',adminName='';try{token=localStorage.getItem('cantina-token')||'';adminName=localStorage.getItem('cantina-admin')||''}catch{}
let page='painel',status='Todos',query='',statementStudent=db.students[0]?.id,month=today().slice(0,7),peopleView='alunos';
const OFFLINE='Sem conexão com a API. Abra o painel em http://localhost:8000/dist/ com o servidor PHP ligado.';
async function api(path,method='GET',body){const headers={};if(body)headers['Content-Type']='application/json';if(token)headers.Authorization=`Bearer ${token}`;let r;try{r=await fetch(`../api/${path}`,{method,headers,body:body?JSON.stringify(body):undefined})}catch{throw new Error(OFFLINE)}const data=await r.json().catch(()=>null);if(data===null)throw new Error(OFFLINE);if(r.status===401&&path!=='login'){endSession();throw new Error('Sessão expirada. Entre novamente.')}if(!r.ok)throw new Error(data.erro||`Erro ${r.status}`);return data}
function store(k,v){try{v?localStorage.setItem(k,v):localStorage.removeItem(k)}catch{}}
function endSession(){token='';adminName='';store('cantina-token');store('cantina-admin');db={products:[],students:[],orders:[]};render()}
function loginPage(){return `<form class="login" onsubmit="doLogin(event)"><h1>Entrar</h1><p class="muted">Acesso da administração</p>${location.protocol==='file:'?`<p class="alert">Este arquivo foi aberto direto do computador e não alcança a API. Use ${OFFLINE.split(' em ')[1].split(' com')[0]}</p>`:''}<label for="login">Usuário ou CPF</label><input id="login" name="login" required autocomplete="username"><label for="password">Senha</label><input id="password" name="password" type="password" required autocomplete="current-password"><button class="btn primary" type="submit">Entrar</button></form>`}
async function doLogin(e){e.preventDefault();const f=new FormData(e.target),b=e.target.querySelector('button');b.disabled=true;try{const r=await api('login','POST',{type:'admin',login:f.get('login').trim(),password:f.get('password')});token=r.token;adminName=r.name;store('cantina-token',token);store('cantina-admin',adminName);await load()}catch(err){toast(err.message);b.disabled=false}}
async function logout(){try{await api('logout','POST')}catch{}endSession()}
async function load(silent=false){if(!token)return render();try{const next=await api('estado'),changed=JSON.stringify(next)!==JSON.stringify(db);db=next;if(!student(statementStudent))statementStudent=db.students[0]?.id;if(changed||!silent)render()}catch(e){if(!silent&&token)toast(`Não foi possível carregar os dados: ${e.message}`)}}
setInterval(()=>{const a=document.activeElement;if(token&&!document.hidden&&!$('#modal').open&&!(a&&['INPUT','SELECT','TEXTAREA'].includes(a.tagName)))load(true)},15000);
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4200)}function student(id){return db.students.find(s=>s.id===Number(id))}function badge(s){return `<span class="badge ${s==='Pronto'?'ready':s==='Em preparo'?'prep':s==='Cancelado'?'cancel':''}">${s}</span>`}function person(s){return `<div class="person"><div><b>${esc(s.name)}</b><small>${esc(s.class)}</small></div></div>`}function btn(text,action,primary=false){return `<button class="btn ${primary?'primary':''}" onclick="${action}">${text}</button>`}function heading(title,sub,action=''){return `<div class="heading"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`}
function go(p){location.hash=p}function render(){document.body.classList.toggle('auth',!token);$('#admin-name').textContent=adminName||'Administração';if(!token){$('#app').innerHTML=loginPage();return}page=location.hash.slice(1)||'painel';if(!titles[page])page='painel';$('#nav').innerHTML=Object.entries(titles).map(([k,v])=>`<a href="#${k}" class="${k===page?'active':''}">${v}</a>`).join('');$('#crumb').textContent=titles[page];$('#app').innerHTML=({painel:dashboard,pedidos:ordersPage,cardapio:menu,alunos:studentsPage,extratos:statements,relatorios:reports}[page])()}window.addEventListener('hashchange',()=>{query='';status='Todos';render()});
function filteredOrders(iv){return db.orders.filter(o=>o.date===today()&&o.interval===iv&&o.status!=='Cancelado'&&(status==='Todos'||o.status===status)&&(`${student(o.student).name} ${o.id}`).toLowerCase().includes(query.toLowerCase()))}function orderTable(limit,iv){const orders=filteredOrders(iv).slice(0,limit||999);return `<div class="table-wrap"><table><thead><tr><th>Aluno</th><th>Pedido</th><th>Status</th><th></th></tr></thead><tbody>${orders.map(o=>{const s=student(o.student);return `<tr><td><span class="code">R${o.id}</span>${person(s)}</td><td>${o.items.map(i=>`${i.qty}× ${esc(i.name)}${i.observation?`<small>Obs.: ${esc(i.observation)}</small>`:''}`).join('<br>')}${s.allergy?`<small class="alert">${esc(s.allergy)}</small>`:''}</td><td>${badge(o.status)}</td><td class="right">${o.status==='Entregue'?'<span class="muted">Retirado</span>':`<div class="actions"><button class="btn small" onclick="advance(${o.id})">${o.status==='Pronto'?'Entregar':'Marcar pronto'}</button><button class="text-danger" onclick="askCancel(${o.id})">Cancelar</button></div>`}</td></tr>`}).join('')||'<tr><td colspan="4" class="empty">Nenhum pedido</td></tr>'}</tbody></table></div>`}async function advance(id){const o=db.orders.find(o=>o.id===id);if(!o||!['Pronto','Em preparo'].includes(o.status))return;const next=o.status==='Pronto'?'Entregue':'Pronto';try{await api(`pedidos/${id}`,'PATCH',{status:next});o.status=next;render();toast(`R${id} ${next==='Entregue'?'entregue':'pronto'}`)}catch(e){toast(e.message)}}
function toolbar(){return `<div class="toolbar"><input aria-label="Buscar pedido" class="search" placeholder="Buscar por nome ou código" value="${esc(query)}" oninput="query=this.value;updateTable()"><div class="tabs">${['Todos','Em preparo','Pronto','Entregue'].map(s=>`<button class="${status===s?'active':''}" onclick="status='${s}';render()">${s}</button>`).join('')}</div></div>`}function updateTable(){intervals.forEach(([t,,key])=>{const el=$(`#order-table-${key}`);if(el)el.innerHTML=orderTable(page==='painel'?4:999,t)})}
function dashboard(){const active=db.orders.filter(o=>o.date===today()&&o.status!=='Cancelado'),count=s=>active.filter(o=>o.status===s).length,h=new Date().getHours(),date=new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'}),stats=[['Pedidos hoje',active.length],['Em preparo',count('Em preparo')],['Prontos',count('Pronto')],['Entregues',count('Entregue')]];const prep=t=>{const p={};active.filter(o=>o.interval===t&&o.status!=='Entregue').forEach(o=>o.items.forEach(i=>p[i.name]=(p[i.name]||0)+i.qty));return Object.entries(p).map(([n,q])=>`<div class="prep-item"><span>${esc(n)}</span><span class="quantity">${q}</span></div>`).join('')||'<p class="empty">Nada pendente</p>'};return heading(`${h<12?'Bom dia':h<18?'Boa tarde':'Boa noite'}${adminName?`, ${esc(adminName.split(' ')[0])}`:''}`,date[0].toUpperCase()+date.slice(1))+`<section class="stats">${stats.map(([l,v])=>`<div class="stat"><span>${l}</span><strong>${v}</strong></div>`).join('')}</section><div class="grid"><section class="card"><div class="card-title"><h2>Fila de retirada</h2><a href="#pedidos" class="text-btn">Ver todos</a></div>${toolbar()}${intervals.map(([t,label,key])=>groupTitle(label,t)+`<div id="order-table-${key}">${orderTable(4,t)}</div>`).join('')}</section><section class="card"><div class="card-title"><h2>Preparar</h2></div>${intervals.map(([t,label])=>groupTitle(label,t)+`<div class="preparation">${prep(t)}</div>`).join('')}</section></div>`}
function groupTitle(label,t){return `<div class="group-title">${t} <span>${label}</span></div>`}

const intervals=[['09:00','Manhã','manha'],['15:30','Tarde','tarde']];
function ordersPage(){return heading('Pedidos')+`<div class="filters">${toolbar()}</div><div class="stack">${intervals.map(([t,label,key])=>{const n=db.orders.filter(o=>o.date===today()&&o.interval===t&&!['Entregue','Cancelado'].includes(o.status)).length;return `<section class="card"><div class="card-title"><h2>${t} <span class="muted">${label}</span></h2><span class="muted">${n} a retirar</span></div><div id="order-table-${key}">${orderTable(999,t)}</div></section>`}).join('')}</div>`}

function menu(){return heading('Cardápio','',btn('Novo item','productModal()',true))+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Item</th><th>Categoria</th><th>Horário</th><th>Preço</th><th>Situação</th><th></th></tr></thead><tbody>${db.products.map(p=>`<tr><td><b>${esc(p.name)}</b>${p.description?`<small>${esc(p.description)}</small>`:''}</td><td>${esc(p.category)}${p.flavor?`<small>${esc(p.flavor)}</small>`:''}</td><td class="num">${esc(p.time||'')}</td><td class="num">${money(p.price)}</td><td><span class="badge ${p.available?'ready':''}">${p.available?'Disponível':'Esgotado'}</span></td><td class="right"><div class="actions"><button class="btn small" onclick="productModal(${p.id})">Editar</button><button class="btn small" onclick="toggleProduct(${p.id})">${p.available?'Esgotar':'Disponibilizar'}</button><button class="text-danger" onclick="askDelete(${p.id})">Excluir</button></div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nenhum item</td></tr>'}</tbody></table></div></section>`}function confirmBox(title,text,label,action){modal(`<h2>${title}</h2><p class="muted">${text}</p><form onsubmit="event.preventDefault();closeModal();${action}">${dialogActions(label,'Voltar')}</form>`)}
function askCancel(id){const o=db.orders.find(o=>o.id===id);if(!o)return;confirmBox(`Cancelar pedido R${id}?`,`${esc(student(o.student)?.name||'')}: ${o.items.map(i=>`${i.qty}× ${esc(i.name)}`).join(', ')}. Se houve débito do saldo, o valor será devolvido.`,'Cancelar pedido',`cancelOrder(${id})`)}
async function cancelOrder(id){try{const r=await api(`pedidos/${id}`,'PATCH',{status:'Cancelado'});await load();toast(r.refunded?`R${id} cancelado · ${money(r.refunded)} devolvido ao saldo`:`R${id} cancelado`)}catch(e){toast(e.message)}}
function askDelete(id){const p=db.products.find(p=>p.id===id);if(!p)return;confirmBox(`Excluir ${esc(p.name)}?`,'O item sai do cardápio e do app. Pedidos antigos com ele continuam no histórico.','Excluir',`deleteProduct(${id})`)}
async function deleteProduct(id){const p=db.products.find(p=>p.id===id);try{await api(`produtos/${id}`,'DELETE');await load();toast(`${p?.name||'Item'} excluído`)}catch(e){toast(e.message)}}
async function toggleProduct(id){const p=db.products.find(p=>p.id===id);try{await api(`produtos/${id}`,'PATCH',{available:!p.available});p.available=!p.available;render();toast(`${p.name}: ${p.available?'disponível':'esgotado'}`)}catch(e){toast(e.message)}}function modal(content){$('#modal-content').innerHTML=content;$('#modal').showModal()}function closeModal(){$('#modal').close()}function dialogActions(label='Salvar',back='Cancelar'){return `<div class="dialog-actions"><button type="button" class="btn" onclick="closeModal()">${back}</button><button class="btn primary" type="submit">${label}</button></div>`}function productModal(id){const p=db.products.find(p=>p.id===id)||{name:'',description:'',category:'Salgados',flavor:'',time:'09:00',price:0};modal(`<h2>${id?'Editar item':'Novo item'}</h2><form onsubmit="saveProduct(event,${id||0})"><label for="name">Nome</label><input id="name" name="name" required maxlength="100" value="${esc(p.name)}"><label for="description">Descrição</label><input id="description" name="description" required maxlength="400" value="${esc(p.description)}"><label for="category">Categoria</label><input id="category" name="category" required maxlength="50" value="${esc(p.category)}"><label for="flavor">Sabor</label><input id="flavor" name="flavor" required maxlength="100" value="${esc(p.flavor)}"><label for="time">Horário</label><input id="time" name="time" type="time" required value="${esc(p.time)}"><label for="price">Preço (R$)</label><input id="price" name="price" type="number" min="0.01" step="0.01" required value="${p.price/100||''}">${dialogActions()}</form>`)}async function saveProduct(e,id){e.preventDefault();const f=new FormData(e.target),p={name:f.get('name').trim(),description:f.get('description').trim(),category:f.get('category').trim(),flavor:f.get('flavor').trim(),time:f.get('time'),price:Math.round(Number(f.get('price'))*100)};if(!p.name||p.price<=0)return;try{await api(id?`produtos/${id}`:'produtos',id?'PUT':'POST',p);closeModal();await load();toast('Item salvo')}catch(e){toast(e.message)}}
function peopleTabs(){return `<div class="tabs">${[['alunos','Alunos'],['responsaveis','Responsáveis']].map(([k,v])=>`<button class="${peopleView===k?'active':''}" onclick="peopleView='${k}';render()">${v}</button>`).join('')}</div>`}
function parentsTable(){const parents={};db.students.forEach(s=>(parents[s.parent]=parents[s.parent]||[]).push(s));return `<div class="table-wrap"><table><thead><tr><th>Responsável</th><th>Alunos</th><th></th></tr></thead><tbody>${Object.entries(parents).map(([p,list])=>`<tr><td><b>${esc(p)}</b></td><td>${list.map(s=>`<div style="margin:4px 0">${esc(s.name)} <span class="muted">${esc(s.class)}</span></div>`).join('')}</td><td class="right"><div class="actions">${list.map(s=>`<button class="btn small" onclick="statementStudent=${s.id};go('extratos')">${list.length>1?`Pedidos de ${esc(s.name.split(' ')[0])}`:'Ver pedidos'}</button>`).join('')}</div></td></tr>`).join('')||'<tr><td colspan="3" class="empty">Nenhum responsável</td></tr>'}</tbody></table></div>`}
function studentsPage(){return heading('Alunos e responsáveis','',peopleTabs())+`<section class="card">${peopleView==='responsaveis'?parentsTable():`<div class="table-wrap"><table><thead><tr><th>Aluno</th><th>Responsável</th><th>Saldo</th><th></th></tr></thead><tbody>${db.students.map(s=>`<tr><td>${person(s)}</td><td>${esc(s.parent)}</td><td class="num">${money(s.balance||0)}</td><td class="right"><button class="btn small" onclick="statementStudent=${s.id};go('extratos')">Ver pedidos</button></td></tr>`).join('')}</tbody></table></div>`}</section>`}
function statementRows(){return db.orders.filter(o=>o.student===Number(statementStudent)&&o.date.startsWith(month))}
function statements(){const rows=statementRows();return heading('Histórico','',btn('Exportar CSV','exportMonth()'))+`<div class="filters"><select aria-label="Aluno" style="width:250px" onchange="statementStudent=Number(this.value);render()">${db.students.map(s=>`<option value="${s.id}" ${s.id===Number(statementStudent)?'selected':''}>${esc(s.name)}</option>`).join('')}</select><input aria-label="Mês dos pedidos" type="month" value="${month}" style="width:180px" onchange="month=this.value;render()"></div><section class="card"><div class="summary"><div><small>Pedidos no mês</small><strong>${rows.length}</strong></div><div><small>Entregues</small><strong>${rows.filter(o=>o.status==='Entregue').length}</strong></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Código</th><th>Intervalo</th><th>Itens</th><th>Status</th></tr></thead><tbody>${[...rows].reverse().map(o=>`<tr><td class="num">${esc(o.date.split('-').reverse().join('/'))}</td><td class="code">R${o.id}</td><td>${esc(o.interval)}</td><td>${o.items.map(i=>`${i.qty}× ${esc(i.name)}${i.observation?`<small>Obs.: ${esc(i.observation)}</small>`:''}`).join('<br>')}</td><td>${badge(o.status)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nenhum pedido neste mês</td></tr>'}</tbody></table></div></section>`}
function exportMonth(){const safe=v=>'"'+String(v).replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const rows=[['Aluno','Responsável','Data','Código','Intervalo','Item','Quantidade','Status']];statementRows().forEach(o=>{const s=student(o.student);o.items.forEach(i=>rows.push([s.name,s.parent,o.date,'R'+o.id,o.interval,i.name,i.qty,o.status]))});const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=`pedidos-${month}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV exportado')}
function reports(){return heading('Relatórios')+`<section class="card"><div class="card-title"><h2>Encomendas</h2></div><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Aluno</th><th>Itens</th><th>Pagamento</th><th>Status</th></tr></thead><tbody>${[...db.orders].reverse().map(o=>`<tr><td><span class="code">R${esc(o.id)}</span><small>${esc(o.date.split('-').reverse().join('/'))}</small></td><td>${person(student(o.student))}</td><td>${o.items.map(i=>`${i.qty}× ${esc(i.name)}${i.observation?`<small>Obs.: ${esc(i.observation)}</small>`:''}`).join('<br>')}<small>Retirada ${esc(o.interval)}</small></td><td>${esc(o.paymentMethod||'—')}<small>${esc(o.paymentStatus||'')}</small></td><td>${badge(o.status)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nenhuma encomenda</td></tr>'}</tbody></table></div></section>`}

if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'consultar_pedidos',title:'Consultar pedidos do intervalo',description:'Lista pedidos fictícios e seus estados, sem alterar dados.',inputSchema:{type:'object',properties:{intervalo:{type:'string',enum:['09:00','15:30']}},required:['intervalo'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!['09:00','15:30'].includes(input.intervalo))throw new Error('Intervalo inválido');return db.orders.filter(o=>o.date===today()&&o.interval===input.intervalo).map(o=>({codigo:`R${o.id}`,aluno:student(o.student).name,status:o.status}));}})).catch(()=>{})}catch{}}
render();load();
